  if [[ -n "$source_dir" ]]; then rm -rf -- "$source_dir" || result=1; fi
  if (( result != 0 )); then echo "FAIL: V5.16 review gate status=$result";
  else echo 'PASS: V5.16 review gates completed; cutover, push and merge DENIED'; fi
  exit "$result"
}
